function validate([points, w]) {
  if (!Array.isArray(points) || points.length < 1 || points.length > 100000) return 'points needs 1 to 10^5 points.';
  const seen = new Set();
  for (const p of points) {
    if (!Array.isArray(p) || p.length !== 2 || p.some(v => !Number.isInteger(v) || v < 0 || v > 1000000000)) return 'Each point is [x, y] with integers from 0 to 10^9.';
    const key = p[0] + ',' + p[1];
    if (seen.has(key)) return 'All points must be distinct.';
    seen.add(key);
  }
  if (!Number.isInteger(w) || w < 0 || w > 1000000000) return 'w is an integer from 0 to 10^9.';
  return null;
}

