function minRectanglesToCoverPoints(points, w) {
  const xs = points.map((point) => point[0]);
  xs.sort((a, b) => a - b);
  let rectangles = 0;
  let coveredUntil = -1;

  for (const x of xs) {
    if (x > coveredUntil) {
      rectangles++;
      coveredUntil = x + w;
    }
  }
  return rectangles;
}

