function minRectanglesToCoverPoints(points, w) {
  // DP over the distinct x values: the last rectangle covers some block values[j..i-1] whose width is at most w.
  const values = [...new Set(points.map(p => p[0]))].sort((a, b) => a - b);
  const fewest = [0];
  for (let i = 1; i <= values.length; i++) {
    fewest[i] = Infinity;
    for (let j = 0; j < i; j++) {
      if (values[i - 1] - values[j] <= w) fewest[i] = Math.min(fewest[i], fewest[j] + 1);
    }
  }
  return fewest[values.length];
}

