function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? 2000 : int(1, 8);
  const xTop = large ? [3000, 1000000, 1000000000][int(0, 2)] : [5, 20, 1000000000][int(0, 2)];
  const yTop = [3, 1000000000][int(0, 1)];
  // w is zero, tiny, near the typical gap between points (the interesting range), or the maximum.
  const typical = Math.min(1000000000, Math.floor(xTop * 3 / n));
  const w = [0, int(0, 3), int(0, typical), int(0, typical), 1000000000][int(0, 4)];
  // Points must be distinct, so draw until there are n different ones.
  const seen = new Set();
  const points = [];
  while (points.length < n) {
    const x = int(0, xTop);
    const y = int(0, yTop);
    if (seen.has(x + ',' + y)) continue;
    seen.add(x + ',' + y);
    points.push([x, y]);
  }
  return [points, w];
}
